import { useAuth } from "@/_core/hooks/useAuth";
import PortalShell from "@/components/PortalShell";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Progress } from "@/components/ui/progress";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { AUTOSAVE_DELAY_MS, publishAutosaveStatus } from "@/lib/assessmentSafety";
import { AlertTriangle, ArrowLeft, Bell, BriefcaseBusiness, Camera, Check, ChevronLeft, ChevronRight, CircleCheck, Clock3, Code2, Eye, FileCode2, FileUp, Filter, Flag, GitCompareArrows, Layers3, LayoutDashboard, LockKeyhole, MessageSquareText, MonitorUp, MoreVertical, Plus, Search, ShieldAlert, ShieldCheck, Sparkles, TimerReset, UserRound, UsersRound, Video, X } from "lucide-react";
import { type ComponentType, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";
import { Link, useLocation, useRoute } from "wouter";

type Status = "accepted" | "rejected" | "under review" | null;
type QuestionType = "multiple_choice" | "essay" | "code" | "vulnerability" | "file_upload";
type DraftQuestion = { type: QuestionType; prompt: string; guidance?: string; points: number; options?: { id: string; label: string }[]; correctAnswers?: string[]; starterCode?: string; supportedLanguages?: string[] };
type DraftSection = { title: string; instructions: string; questions: DraftQuestion[] };

const labels: Record<QuestionType, string> = { multiple_choice: "اختيار من متعدد", essay: "إجابة مقالية", code: "كتابة كود", vulnerability: "اكتشاف ثغرة", file_upload: "رفع ملف" };
const statusStyle: Record<Exclude<Status, null>, string> = { accepted: "border-emerald-300/20 bg-emerald-400/10 text-emerald-300", rejected: "border-rose-300/20 bg-rose-400/10 text-rose-300", "under review": "border-amber-300/20 bg-amber-400/10 text-amber-200" };

function PageHeader({ eyebrow, title, text, action }: { eyebrow: string; title: string; text?: string; action?: React.ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="eyebrow">{eyebrow}</p><h1 className="mt-2 text-3xl font-semibold tracking-tight text-white md:text-4xl">{title}</h1>{text && <p className="mt-3 max-w-2xl text-sm leading-7 text-slate-400">{text}</p>}</div>{action}</div>;
}
function Metric({ label, value, hint, icon: Icon }: { label: string; value: string | number; hint: string; icon: ComponentType<{ className?: string }> }) { return <div className="metric-card"><div className="flex items-start justify-between"><div><p className="text-xs text-slate-400">{label}</p><p className="mt-3 text-3xl font-semibold text-white">{value}</p></div><span className="grid h-9 w-9 place-items-center rounded-xl bg-cyan-300/10 text-cyan-200"><Icon className="h-4 w-4"/></span></div><p className="mt-4 text-[11px] text-slate-500">{hint}</p></div>; }
function StatusPill({ status }: { status: Status }) { const text = status ?? "under review"; return <Badge variant="outline" className={`rounded-full px-2.5 py-1 text-[11px] font-medium ${statusStyle[text]}`}>{text === "accepted" ? "مقبول" : text === "rejected" ? "مرفوض" : "تحت المراجعة"}</Badge>; }
function Blank({ title, text, action }: { title: string; text: string; action?: React.ReactNode }) { return <div className="glass-panel grid min-h-64 place-items-center p-8 text-center"><div><div className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-cyan-300/10 text-cyan-200"><Layers3 className="h-5 w-5"/></div><h3 className="mt-4 text-lg font-semibold text-white">{title}</h3><p className="mt-2 max-w-sm text-sm leading-7 text-slate-400">{text}</p>{action && <div className="mt-5">{action}</div>}</div></div>; }
function timeLabel(minutes: number) { return `${minutes} دقيقة`; }
function percent(value: number | null) { return value === null ? "—" : `${value}%`; }
function joinSkills(value: unknown) { return Array.isArray(value) ? value.join(" · ") : ""; }

export function CandidateDashboard() {
  const attempts = trpc.candidate.attempts.list.useQuery();
  const [, setLocation] = useLocation();
  const rows = attempts.data ?? [];
  return <PortalShell role="candidate"><div className="page-wrap"><PageHeader eyebrow="Candidate workspace" title="كل شغلك في مكان واحد." text="اختار اختبار مناسب، خلّصه في وقتك، وتابع حالته من غير لف ودوران." action={<Button onClick={() => setLocation("/discover")} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">استكشف الاختبارات<ArrowLeft className="mr-2 h-4 w-4"/></Button>}/><div className="grid gap-4 md:grid-cols-3"><Metric label="كل المحاولات" value={rows.length} hint="محاولاتك الحالية والسابقة" icon={ClipboardIcon}/><Metric label="تحت المراجعة" value={rows.filter(row => row.attempt.applicationStatus === "under review").length} hint="بانتظار قرار الشركة" icon={Clock3}/><Metric label="أفضل أولوية" value={rows.length ? `${Math.max(...rows.map(row => row.attempt.priorityScore))}%` : "—"} hint="إشارة ترتيب للمراجعة" icon={Sparkles}/></div><section className="mt-8"><div className="mb-4 flex items-center justify-between"><h2 className="text-lg font-semibold text-white">آخر المحاولات</h2><button onClick={() => setLocation("/candidate/status")} className="text-xs text-cyan-300 hover:text-cyan-100">عرض الكل</button></div>{attempts.isLoading ? <div className="glass-panel h-48 animate-pulse"/> : rows.length ? <div className="glass-panel divide-y soft-divider overflow-hidden">{rows.slice(0, 4).map(row => <button key={row.attempt.id} onClick={() => setLocation("/candidate/status")} className="flex w-full items-center justify-between gap-4 px-5 py-4 text-right transition hover:bg-white/[.025]"><div className="min-w-0"><p className="truncate text-sm font-medium text-white">{row.test.title}</p><p className="mt-1 text-xs text-slate-500">{row.company.name} · {row.test.field}</p></div><div className="flex shrink-0 items-center gap-4"><span className="hidden text-sm text-slate-400 sm:block">{percent(row.attempt.reviewerScore ?? row.attempt.autoScore)}</span><StatusPill status={row.attempt.applicationStatus}/><ChevronLeft className="h-4 w-4 text-slate-600"/></div></button>)}</div> : <Blank title="ابدأ بأول اختبار" text="لما تكمّل اختبار، هيظهر هنا مع حالته ودرجة المراجعة." action={<Button onClick={() => setLocation("/discover")} className="bg-cyan-300 text-slate-950">تصفح الاختبارات</Button>}/>}</section></div></PortalShell>;
}

export function Discover() {
  const [search, setSearch] = useState(""); const [field, setField] = useState("all"); const [company, setCompany] = useState("all"); const [level, setLevel] = useState("all"); const [duration, setDuration] = useState("all"); const [, setLocation] = useLocation();
  const filters = useMemo(() => ({ search: search || undefined, field: field === "all" ? undefined : field, companyId: company === "all" ? undefined : Number(company), level: level === "all" ? undefined : level as "junior" | "mid" | "senior", maxDuration: duration === "all" ? undefined : Number(duration) }), [search, field, company, level, duration]);
  const catalog = trpc.catalog.list.useQuery(filters); const unfilteredCatalog = trpc.catalog.list.useQuery(); const start = trpc.candidate.attempts.start.useMutation({ onSuccess: attempt => setLocation(`/attempt/${attempt.id}`), onError: error => toast.error(error.message) });
  const fields = Array.from(new Set((unfilteredCatalog.data ?? []).map(row => row.test.field))); const companies = Array.from(new Map((unfilteredCatalog.data ?? []).map(row => [row.company.id, row.company])).values());
  return <PortalShell role="candidate"><div className="page-wrap"><PageHeader eyebrow="Assessment catalog" title="اختبار مناسب قبل التقديم." text="فلتر حسب التخصص والمستوى والشركة والمدة، وابدأ لما تكون جاهز."/><div className="glass-panel grid gap-3 p-4 md:grid-cols-[1fr_150px_170px_130px_145px]"><div className="relative"><Search className="absolute right-3 top-3 h-4 w-4 text-slate-500"/><Input value={search} onChange={event => setSearch(event.target.value)} placeholder="دور باسم اختبار أو مهارة..." className="border-white/10 bg-white/[.03] pr-10 text-white placeholder:text-slate-600"/></div><Select value={field} onValueChange={setField}><SelectTrigger className="border-white/10 bg-white/[.03] text-slate-300"><SelectValue placeholder="المجال"/></SelectTrigger><SelectContent><SelectItem value="all">كل المجالات</SelectItem>{fields.map(value => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select><Select value={company} onValueChange={setCompany}><SelectTrigger className="border-white/10 bg-white/[.03] text-slate-300"><SelectValue placeholder="الشركة"/></SelectTrigger><SelectContent><SelectItem value="all">كل الشركات</SelectItem>{companies.map(value => <SelectItem key={value.id} value={String(value.id)}>{value.name}</SelectItem>)}</SelectContent></Select><Select value={level} onValueChange={setLevel}><SelectTrigger className="border-white/10 bg-white/[.03] text-slate-300"><SelectValue placeholder="المستوى"/></SelectTrigger><SelectContent><SelectItem value="all">كل المستويات</SelectItem><SelectItem value="junior">Junior</SelectItem><SelectItem value="mid">Mid</SelectItem><SelectItem value="senior">Senior</SelectItem></SelectContent></Select><Select value={duration} onValueChange={setDuration}><SelectTrigger className="border-white/10 bg-white/[.03] text-slate-300"><SelectValue placeholder="المدة"/></SelectTrigger><SelectContent><SelectItem value="all">أي مدة</SelectItem><SelectItem value="30">حتى 30 دقيقة</SelectItem><SelectItem value="60">حتى ساعة</SelectItem><SelectItem value="120">حتى ساعتين</SelectItem></SelectContent></Select></div><div className="mt-7 grid gap-4 lg:grid-cols-2 xl:grid-cols-3">{catalog.isLoading ? Array.from({ length: 6 }).map((_, index) => <div key={index} className="glass-panel h-64 animate-pulse"/>) : catalog.data?.map(row => <article key={row.test.id} className="glass-panel group flex min-h-64 flex-col p-5"><div className="flex items-start justify-between"><span className="grid h-10 w-10 place-items-center rounded-xl bg-violet-400/10 text-violet-200"><Code2 className="h-5 w-5"/></span><Badge variant="outline" className="border-white/10 text-[10px] text-slate-400">{row.test.level}</Badge></div><h2 className="mt-5 text-lg font-semibold text-white">{row.test.title}</h2><p className="mt-2 line-clamp-2 text-sm leading-6 text-slate-400">{row.test.summary}</p><div className="mt-4 flex flex-wrap gap-2 text-[11px] text-slate-400"><span className="rounded-lg bg-white/[.04] px-2 py-1">{row.company.name}</span><span className="rounded-lg bg-white/[.04] px-2 py-1">{row.test.field}</span><span className="flex items-center gap-1 rounded-lg bg-white/[.04] px-2 py-1"><Clock3 className="h-3 w-3"/>{timeLabel(row.test.durationMinutes)}</span></div><div className="mt-auto flex items-center justify-between pt-6"><span className="text-[11px] text-slate-500">{row.test.proctoringMode === "required" ? "مراقبة مطلوبة" : row.test.proctoringMode === "optional" ? "مراقبة اختيارية" : "بدون مراقبة"}</span><Button size="sm" onClick={() => start.mutate({ testId: row.test.id })} disabled={start.isPending} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">ابدأ<ChevronLeft className="mr-1 h-3.5 w-3.5"/></Button></div></article>)}</div>{!catalog.isLoading && !catalog.data?.length && <Blank title="مفيش اختبارات مطابقة" text="جرّب تعدل الفلاتر أو امسح البحث."/>}</div></PortalShell>;
}

export function CandidateProfile() {
  const profile = trpc.candidate.profile.get.useQuery(); const save = trpc.candidate.profile.save.useMutation({ onSuccess: () => toast.success("تم حفظ ملفك المهني.") });
  const [headline, setHeadline] = useState(""); const [bio, setBio] = useState(""); const [skills, setSkills] = useState(""); const [portfolio, setPortfolio] = useState("");
  useEffect(() => { if (!profile.data) return; setHeadline(profile.data.headline ?? ""); setBio(profile.data.bio ?? ""); setSkills(joinSkills(profile.data.skills)); setPortfolio(Array.isArray(profile.data.portfolioLinks) ? profile.data.portfolioLinks.map(link => `${link.label}|${link.url}`).join("\n") : ""); }, [profile.data]);
  const submit = () => save.mutate({ headline: headline || null, bio: bio || null, skills: skills.split(/[,،]/).map(value => value.trim()).filter(Boolean), experience: [], portfolioLinks: portfolio.split("\n").map(row => row.split("|")).filter(row => row.length === 2 && row[1].startsWith("http")).map(([label, url]) => ({ label: label.trim(), url: url.trim() })) });
  return <PortalShell role="candidate"><div className="page-wrap max-w-4xl"><PageHeader eyebrow="Professional profile" title="ملفك المهني." text="خليه مختصر وواضح، لأنه بيتعرض للشركة مع المحاولة بعد التسليم."/><div className="glass-panel p-6 md:p-8"><div className="grid gap-6"><label className="grid gap-2 text-sm text-slate-300">العنوان المهني<Input value={headline} onChange={event => setHeadline(event.target.value)} placeholder="مثال: Junior Web Penetration Tester" className="border-white/10 bg-white/[.03] text-white"/></label><label className="grid gap-2 text-sm text-slate-300">نبذة سريعة<Textarea value={bio} onChange={event => setBio(event.target.value)} rows={5} placeholder="اشرح خبرتك ونوع الشغل اللي بتستهدفه..." className="border-white/10 bg-white/[.03] text-white"/></label><label className="grid gap-2 text-sm text-slate-300">المهارات<Input value={skills} onChange={event => setSkills(event.target.value)} placeholder="Burp Suite، OWASP، JavaScript، Linux" className="border-white/10 bg-white/[.03] text-white"/></label><label className="grid gap-2 text-sm text-slate-300">روابط الأعمال<Textarea value={portfolio} onChange={event => setPortfolio(event.target.value)} rows={4} placeholder="GitHub|https://github.com/username\nPortfolio|https://example.com" className="border-white/10 bg-white/[.03] font-mono text-white"/></label></div><div className="mt-7 flex justify-end"><Button onClick={submit} disabled={save.isPending} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">{save.isPending ? "جاري الحفظ..." : "حفظ الملف"}<Check className="mr-2 h-4 w-4"/></Button></div></div></div></PortalShell>;
}

export function LegacyCandidateStatus() { const attempts = trpc.candidate.attempts.list.useQuery(); return <PortalShell role="candidate"><div className="page-wrap"><PageHeader eyebrow="Application tracking" title="حالة كل محاولة." text="تحديثات الحالة بتظهر هنا بعد مراجعة الشركة."/>{attempts.data?.length ? <div className="glass-panel overflow-hidden"><div className="overflow-auto"><table className="w-full min-w-[680px] text-right text-sm"><thead className="border-b soft-divider bg-white/[.02] text-xs text-slate-500"><tr><th className="px-5 py-4 font-medium">الاختبار</th><th className="px-5 py-4 font-medium">الشركة</th><th className="px-5 py-4 font-medium">النتيجة</th><th className="px-5 py-4 font-medium">الأولوية</th><th className="px-5 py-4 font-medium">الحالة</th></tr></thead><tbody className="divide-y soft-divider">{attempts.data.map(row => <tr key={row.attempt.id}><td className="px-5 py-4 font-medium text-white">{row.test.title}</td><td className="px-5 py-4 text-slate-400">{row.company.name}</td><td className="px-5 py-4 text-slate-300">{percent(row.attempt.reviewerScore ?? row.attempt.autoScore)}</td><td className="px-5 py-4"><span className="mono text-cyan-200">{row.attempt.priorityScore}</span></td><td className="px-5 py-4"><StatusPill status={row.attempt.applicationStatus}/></td></tr>)}</tbody></table></div></div> : <Blank title="لسه مفيش محاولات" text="ابدأ اختبار عشان تتابع حالته هنا." action={<Link href="/discover"><Button className="bg-cyan-300 text-slate-950">استكشف الاختبارات</Button></Link>}/>}</div></PortalShell>; }

export function NotificationsPage() { const { user } = useAuth(); const notices = trpc.notifications.list.useQuery(); const mark = trpc.notifications.markRead.useMutation({ onSuccess: () => notices.refetch() }); const role = user?.role === "company" ? "company" : "candidate"; return <PortalShell role={role}><div className="page-wrap max-w-4xl"><PageHeader eyebrow="Notifications" title="آخر التنبيهات." text="هنبعت لك تنبيه داخل المنصة عند تغيير حالة التقديم. البريد الخارجي بيتفعل لما تتوصل مزود الرسائل."/>{notices.data?.length ? <div className="glass-panel divide-y soft-divider overflow-hidden">{notices.data.map(notice => <button key={notice.id} onClick={() => !notice.readAt && mark.mutate({ notificationId: notice.id })} className="flex w-full items-start gap-4 p-5 text-right transition hover:bg-white/[.025]"><span className={`mt-1 h-2.5 w-2.5 rounded-full ${notice.readAt ? "bg-slate-700" : "bg-cyan-300 shadow-[0_0_16px_rgba(103,232,249,.8)]"}`}/><div className="min-w-0 flex-1"><p className="font-medium text-white">{notice.title}</p><p className="mt-1 text-sm leading-6 text-slate-400">{notice.content}</p><p className="mt-2 text-[11px] text-slate-600">{new Date(notice.createdAt).toLocaleString("ar-EG")}</p></div></button>)}</div> : <Blank title="مفيش تنبيهات جديدة" text="أول ما شركة تراجع محاولة أو توصلك تحديثات هتظهر هنا."/>}</div></PortalShell>; }

export function CompanyProfile() {
  const profile = trpc.company.profile.get.useQuery(); const update = trpc.company.profile.update.useMutation({ onSuccess: () => { toast.success("تم حفظ بيانات الشركة."); profile.refetch(); } }); const logo = trpc.company.profile.uploadLogo.useMutation({ onSuccess: () => { toast.success("تم رفع الشعار."); profile.refetch(); } });
  const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [website, setWebsite] = useState(""); const [industry, setIndustry] = useState("");
  useEffect(() => { const company = profile.data?.company; if (!company) return; setName(company.name); setDescription(company.description ?? ""); setWebsite(company.website ?? ""); setIndustry(company.industry ?? ""); }, [profile.data]);
  const uploadLogo = (file: File | undefined) => { if (!file) return; const reader = new FileReader(); reader.onload = () => logo.mutate({ fileName: file.name, mimeType: file.type || "image/png", dataBase64: String(reader.result).split(",")[1] ?? "" }); reader.readAsDataURL(file); };
  return <PortalShell role="company"><div className="page-wrap max-w-4xl"><PageHeader eyebrow="Company profile" title="واجهة شركتك." text="البيانات دي بتظهر للمرشحين في صفحة الشركة وصفحات الاختبارات."/>{profile.data ? <div className="glass-panel p-6 md:p-8"><div className="flex flex-wrap items-center gap-5 border-b soft-divider pb-6"><div className="grid h-16 w-16 place-items-center overflow-hidden rounded-2xl border border-white/10 bg-violet-300/10 text-lg font-bold text-violet-100">{profile.data.company.logoKey ? <img src={`/manus-storage/${profile.data.company.logoKey}`} alt="Company logo" className="h-full w-full object-cover"/> : name.slice(0, 1)}</div><div><p className="font-semibold text-white">شعار الشركة</p><p className="mt-1 text-xs text-slate-500">PNG / JPEG / WebP / SVG — حتى 2MB</p><Input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" onChange={event => uploadLogo(event.target.files?.[0])} className="mt-3 max-w-xs border-white/10 bg-white/[.03] text-xs text-slate-300"/></div></div><div className="mt-7 grid gap-6"><label className="grid gap-2 text-sm text-slate-300">اسم الشركة<Input value={name} onChange={event => setName(event.target.value)} className="border-white/10 bg-white/[.03] text-white"/></label><label className="grid gap-2 text-sm text-slate-300">نبذة الشركة<Textarea value={description} onChange={event => setDescription(event.target.value)} rows={5} className="border-white/10 bg-white/[.03] text-white"/></label><div className="grid gap-5 md:grid-cols-2"><label className="grid gap-2 text-sm text-slate-300">الموقع<Input value={website} onChange={event => setWebsite(event.target.value)} placeholder="https://company.com" className="border-white/10 bg-white/[.03] text-white"/></label><label className="grid gap-2 text-sm text-slate-300">الصناعة<Input value={industry} onChange={event => setIndustry(event.target.value)} placeholder="Cybersecurity" className="border-white/10 bg-white/[.03] text-white"/></label></div></div><div className="mt-7 flex items-center justify-between"><Link href={`/companies/${profile.data.company.slug}`} className="text-xs text-cyan-300">افتح الصفحة العامة</Link><Button onClick={() => update.mutate({ name, description: description || null, website: website || null, industry: industry || null })} disabled={update.isPending} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">حفظ البيانات</Button></div></div> : <div className="glass-panel h-80 animate-pulse"/>}</div></PortalShell>;
}

export function CompanyPublicPage() { const [, params] = useRoute("/companies/:slug"); const page = trpc.catalog.companyPage.useQuery({ slug: params?.slug ?? "" }, { enabled: Boolean(params?.slug) }); const [, setLocation] = useLocation(); if (page.isLoading) return <div className="grid min-h-screen place-items-center bg-[#07101f] text-slate-400">جاري تحميل صفحة الشركة...</div>; if (!page.data) return <div className="grid min-h-screen place-items-center bg-[#07101f] text-slate-400">صفحة الشركة غير متاحة.</div>; const { company, tests } = page.data; return <div className="min-h-screen bg-[#07101f] text-white" dir="rtl"><header className="mx-auto flex max-w-6xl items-center justify-between px-6 py-6"><button onClick={() => setLocation("/")} className="font-bold">SkillForge</button><Button onClick={() => setLocation("/discover")} variant="outline" className="border-white/10 bg-white/[.02] text-slate-300 hover:bg-white/10 hover:text-white">كل الاختبارات</Button></header><main className="mx-auto max-w-6xl px-6 pb-16"><section className="glass-panel overflow-hidden p-7 md:p-10"><div className="flex items-start gap-5"><div className="grid h-16 w-16 shrink-0 place-items-center overflow-hidden rounded-2xl bg-violet-300/10 text-xl font-bold text-violet-100">{company.logoKey ? <img src={`/manus-storage/${company.logoKey}`} alt="Company logo" className="h-full w-full object-cover"/> : company.name.slice(0, 1)}</div><div><p className="eyebrow">Company profile</p><h1 className="mt-2 text-3xl font-semibold">{company.name}</h1><p className="mt-3 max-w-2xl leading-8 text-slate-400">{company.description || "شركة تقنية تستخدم SkillForge لتقييم المهارات العملية."}</p><div className="mt-4 flex flex-wrap gap-2 text-xs text-slate-400"><span className="rounded-lg bg-white/[.04] px-2 py-1">{company.industry || "Technology"}</span>{company.website && <a href={company.website} target="_blank" rel="noreferrer" className="rounded-lg bg-white/[.04] px-2 py-1 text-cyan-200">الموقع الإلكتروني</a>}</div></div></div></section><section className="mt-9"><p className="eyebrow">Open assessments</p><h2 className="mt-2 text-2xl font-semibold">الاختبارات المفتوحة</h2><div className="mt-5 grid gap-4 md:grid-cols-2">{tests.map(test => <article key={test.id} className="glass-panel p-5"><h3 className="font-semibold text-white">{test.title}</h3><p className="mt-2 text-sm leading-6 text-slate-400">{test.summary}</p><div className="mt-4 flex items-center justify-between"><span className="text-xs text-slate-500">{test.field} · {timeLabel(test.durationMinutes)}</span><Button size="sm" onClick={() => setLocation("/discover")} className="bg-cyan-300 text-slate-950">عرض</Button></div></article>)}</div>{!tests.length && <Blank title="لا توجد اختبارات مفتوحة" text="تابع الشركة لحد ما تنشر اختبار جديد."/>}</section></main></div>; }

export function SecureFilesPage() { const { user } = useAuth(); const files = trpc.files.listMine.useQuery(); const utils = trpc.useUtils(); const [openingId, setOpeningId] = useState<number | null>(null); const role = user?.role === "company" ? "company" : "candidate"; const openFile = async (assetId: number) => { setOpeningId(assetId); try { const result = await utils.files.secureAccess.fetch({ assetId }); window.open(result.url, "_blank", "noopener,noreferrer"); } catch (error) { toast.error(error instanceof Error ? error.message : "تعذر إنشاء رابط الوصول المؤقت."); } finally { setOpeningId(null); } }; return <PortalShell role={role}><div className="page-wrap"><PageHeader eyebrow="Secure file access" title={role === "company" ? "ملفات المراجعة المؤمنة." : "ملفاتك المؤمنة."} text="كل فتح للملف يمر بتحقق الصلاحية من الخادم ثم يولد رابطًا مؤقتًا؛ مش رابط عام ثابت."/>{files.isLoading ? <div className="glass-panel h-64 animate-pulse"/> : files.error ? <Blank title="تعذر تحميل الملفات" text="حصلت مشكلة أثناء جلب الملفات. جرّب تاني بعد لحظات." action={<Button onClick={() => files.refetch()} className="bg-cyan-300 text-slate-950">إعادة المحاولة</Button>}/> : files.data?.length ? <div className="glass-panel divide-y soft-divider overflow-hidden">{files.data.map(row => <div key={row.asset.id} className="flex flex-wrap items-center justify-between gap-4 p-5"><div className="min-w-0"><p className="truncate text-sm font-medium text-white">{row.asset.originalName}</p><p className="mt-1 text-xs text-slate-500">{row.test?.title ?? "ملف مرتبط بحسابك"} · {row.company?.name ?? ""}</p><div className="mt-2 flex flex-wrap gap-2"><Badge variant="outline" className="border-white/10 text-[10px] text-slate-400">{row.asset.category.replace("_", " ")}</Badge><span className="mono text-[10px] text-slate-600">{Math.ceil(row.asset.byteSize / 1024)} KB</span></div></div><Button size="sm" variant="outline" onClick={() => openFile(row.asset.id)} disabled={openingId === row.asset.id} className="border-cyan-300/20 bg-cyan-300/5 text-cyan-100 hover:bg-cyan-300/10 hover:text-white"><LockKeyhole className="ml-1 h-3.5 w-3.5"/>{openingId === row.asset.id ? "جاري تجهيز الرابط..." : "فتح مؤقت"}</Button></div>)}</div> : <Blank title="لا توجد ملفات" text="المرفقات والأدلة وتسجيلات الجلسات هتظهر هنا بمجرد حفظها."/>}</div></PortalShell>; }

export function DiscoverCatalog() { const probe = trpc.catalog.list.useQuery(); if (probe.isLoading) return <PortalShell role="candidate"><div className="page-wrap"><PageHeader eyebrow="Assessment catalog" title="جاري تجهيز الكتالوج..."/><div className="glass-panel h-72 animate-pulse"/></div></PortalShell>; if (probe.error) return <PortalShell role="candidate"><div className="page-wrap"><PageHeader eyebrow="Assessment catalog" title="تعذر تحميل الاختبارات." text="حصلت مشكلة مؤقتة أثناء جلب الكتالوج، ومش هنعتبرها نتيجة بحث فارغة." action={<Button onClick={() => probe.refetch()} className="bg-cyan-300 text-slate-950">إعادة المحاولة</Button>}/><Blank title="الكتالوج غير متاح حاليًا" text="جرّب تاني بعد لحظات. لو المشكلة استمرت، تواصل مع إدارة المنصة."/></div></PortalShell>; return <Discover />; }

export function CompanyDashboard() {
  const { user } = useAuth(); const data = trpc.company.dashboard.useQuery(undefined, { enabled: user?.role === "company" }); const [, setLocation] = useLocation();
  if (user?.role !== "company") return <CompanyActivation />;
  const dashboard = data.data;
  return <PortalShell role="company"><div className="page-wrap"><PageHeader eyebrow="Company command center" title={dashboard ? `مرحبًا، ${dashboard.company.name}` : "لوحة الشركة"} text="راقب الاختبارات والمحاولات، وابدأ المراجعة من أعلى أولوية." action={<Button onClick={() => setLocation("/company/create-test")} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200"><Plus className="ml-1 h-4 w-4"/>اختبار جديد</Button>}/>{dashboard ? <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="اختبارات منشورة" value={dashboard.metrics.publishedTests} hint="اختبارات ظاهرة للمرشحين" icon={Layers3}/><Metric label="كل المحاولات" value={dashboard.metrics.attempts} hint="لكل اختبارات الشركة" icon={UsersRound}/><Metric label="تحتاج مراجعة" value={dashboard.metrics.pendingReview} hint="محاولات تحت المراجعة" icon={Clock3}/><Metric label="متوسط الأداء" value={`${dashboard.metrics.averagePerformance}%`} hint="درجات المراجع المسجلة" icon={Sparkles}/></div><section className="mt-8"><div className="mb-4 flex items-center justify-between"><h2 className="text-lg font-semibold text-white">أعلى المحاولات أولوية</h2><button onClick={() => setLocation("/company/attempts")} className="text-xs text-cyan-300">كل المحاولات</button></div>{dashboard.recent.length ? <div className="grid gap-3">{dashboard.recent.map(row => <button onClick={() => setLocation(`/company/review/${row.attempt.id}`)} key={row.attempt.id} className="glass-panel flex items-center justify-between gap-4 p-4 text-right transition hover:border-cyan-300/20"><div className="flex min-w-0 items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-violet-300/10 text-xs text-violet-200">{row.candidate.name?.slice(0, 1) ?? "م"}</span><div className="min-w-0"><p className="truncate text-sm font-medium text-white">{row.candidate.name ?? "مرشح"}</p><p className="mt-1 text-xs text-slate-500">{row.test.title}</p></div></div><div className="flex items-center gap-5"><span className="mono text-sm text-cyan-200">{row.attempt.priorityScore}</span><StatusPill status={row.attempt.applicationStatus}/><ChevronLeft className="h-4 w-4 text-slate-600"/></div></button>)}</div> : <Blank title="مافيش محاولات لحد دلوقتي" text="انشر اختبارك الأول وهيبدأ يظهر للمرشحين." action={<Button onClick={() => setLocation("/company/create-test")} className="bg-cyan-300 text-slate-950">أنشئ اختبار</Button>}/>}</section></> : <div className="glass-panel h-80 animate-pulse"/>}</div></PortalShell>;
}

function CompanyActivation() { const activate = trpc.account.activateCompany.useMutation({ onSuccess: () => window.location.reload(), onError: (error: { message: string }) => toast.error(error.message) }); const [name, setName] = useState(""); const [slug, setSlug] = useState(""); return <div className="min-h-screen bg-[#07101f] p-5" dir="rtl"><div className="mx-auto max-w-xl pt-20"><div className="glass-panel p-7 md:p-9"><p className="eyebrow">Company onboarding</p><h1 className="mt-3 text-3xl font-semibold text-white">فعّل مساحة شركتك.</h1><p className="mt-3 text-sm leading-7 text-slate-400">هتقدر تنشر اختبارات وتراجع محاولات شركتك فقط. بيانات المرشحين مش بتخرج عن نطاق الاختبارات الخاصة بيك.</p><div className="mt-7 grid gap-4"><Input value={name} onChange={event => { setName(event.target.value); setSlug(event.target.value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "")); }} placeholder="اسم الشركة" className="border-white/10 bg-white/[.03] text-white"/><Input value={slug} onChange={event => setSlug(event.target.value)} placeholder="company-slug" className="border-white/10 bg-white/[.03] font-mono text-white"/></div><Button onClick={() => activate.mutate({ name, slug, description: null, website: null, industry: null })} disabled={activate.isPending || name.length < 2 || slug.length < 2} className="mt-6 w-full bg-cyan-300 text-slate-950 hover:bg-cyan-200">تفعيل مساحة الشركة</Button></div></div></div>; }

const defaultQuestion = (type: QuestionType): DraftQuestion => ({ type, prompt: type === "multiple_choice" ? "اكتب نص السؤال هنا" : "اكتب تعليمات السؤال بوضوح", guidance: "", points: 10, options: type === "multiple_choice" ? [{ id: "a", label: "اختيار أ" }, { id: "b", label: "اختيار ب" }] : undefined, correctAnswers: type === "multiple_choice" ? ["a"] : undefined, starterCode: type === "code" ? "function solution(input) {\n  // your code\n}" : undefined, supportedLanguages: type === "code" ? ["JavaScript", "Python", "TypeScript"] : undefined });
export function CompanyTestCreator() {
  const [, setLocation] = useLocation(); const create = trpc.company.tests.create.useMutation({ onSuccess: result => { toast.success("تم إنشاء الاختبار."); setLocation("/company/tests"); }, onError: error => toast.error(error.message) });
  const [step, setStep] = useState(1); const [title, setTitle] = useState(""); const [jobTitle, setJobTitle] = useState(""); const [summary, setSummary] = useState(""); const [field, setField] = useState("Web Security"); const [level, setLevel] = useState<"junior" | "mid" | "senior">("junior"); const [duration, setDuration] = useState("60"); const [proctoring, setProctoring] = useState<"none" | "optional" | "required">("optional"); const [sections, setSections] = useState<DraftSection[]>([{ title: "أساسيات التقييم", instructions: "اقرأ كل سؤال كويس قبل الإجابة.", questions: [defaultQuestion("multiple_choice")] }]);
  const updateSection = (index: number, patch: Partial<DraftSection>) => setSections(previous => previous.map((section, current) => current === index ? { ...section, ...patch } : section));
  const updateQuestion = (sectionIndex: number, questionIndex: number, patch: Partial<DraftQuestion>) => setSections(previous => previous.map((section, current) => current !== sectionIndex ? section : { ...section, questions: section.questions.map((question, questionCurrent) => questionCurrent === questionIndex ? { ...question, ...patch } : question) }));
  const addQuestion = (sectionIndex: number, type: QuestionType) => setSections(previous => previous.map((section, current) => current === sectionIndex ? { ...section, questions: [...section.questions, defaultQuestion(type)] } : section));
  const submit = () => create.mutate({ title, jobTitle: jobTitle.trim() || null, summary, field, level, durationMinutes: Number(duration), status: "published", proctoringMode: proctoring, sections });
  return <PortalShell role="company"><div className="page-wrap max-w-6xl"><PageHeader eyebrow="Test builder" title="ابنِ اختبارك خطوة بخطوة." text="جهّز المحتوى، رتب الأقسام، وحدد طريقة مراقبة واضحة للمرشح."/><div className="mb-7 flex items-center gap-2">{["بيانات الاختبار", "الأقسام والأسئلة", "المراجعة والنشر"].map((label, index) => <div key={label} className="flex items-center gap-2"><span className={`grid h-7 w-7 place-items-center rounded-full text-xs ${step >= index + 1 ? "bg-cyan-300 text-slate-950" : "bg-white/5 text-slate-500"}`}>{index + 1}</span><span className={`hidden text-xs md:block ${step === index + 1 ? "text-white" : "text-slate-500"}`}>{label}</span>{index < 2 && <span className="mx-1 h-px w-7 bg-white/10"/>}</div>)}</div><div className="glass-panel p-6 md:p-8">{step === 1 && <div className="grid gap-6"><div className="grid gap-2"><label className="text-sm text-slate-300">اسم الاختبار</label><Input value={title} onChange={event => setTitle(event.target.value)} placeholder="مثال: Junior Web Security Challenge" className="border-white/10 bg-white/[.03] text-white"/></div><div className="grid gap-2"><label className="text-sm text-slate-300">المسمى الوظيفي</label><Input value={jobTitle} onChange={event => setJobTitle(event.target.value)} placeholder="مثال: Junior Web Pentester" className="border-white/10 bg-white/[.03] text-white"/><p className="text-xs text-slate-500">يستخدمه فريقك لتصفية المقارنات. لو تركته فارغًا هيتستخدم اسم الاختبار.</p></div><div className="grid gap-2"><label className="text-sm text-slate-300">وصف للمرشح</label><Textarea value={summary} onChange={event => setSummary(event.target.value)} rows={4} placeholder="وضح المهارات المطلوبة وما الذي سيقيسه الاختبار..." className="border-white/10 bg-white/[.03] text-white"/></div><div className="grid gap-4 md:grid-cols-3"><div className="grid gap-2"><label className="text-sm text-slate-300">المجال</label><Input value={field} onChange={event => setField(event.target.value)} className="border-white/10 bg-white/[.03] text-white"/></div><div className="grid gap-2"><label className="text-sm text-slate-300">المستوى</label><Select value={level} onValueChange={value => setLevel(value as typeof level)}><SelectTrigger className="border-white/10 bg-white/[.03] text-slate-300"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="junior">Junior</SelectItem><SelectItem value="mid">Mid</SelectItem><SelectItem value="senior">Senior</SelectItem></SelectContent></Select></div><div className="grid gap-2"><label className="text-sm text-slate-300">المدة بالدقيقة</label><Input type="number" min="5" value={duration} onChange={event => setDuration(event.target.value)} className="border-white/10 bg-white/[.03] text-white"/></div></div><div className="grid gap-2"><label className="text-sm text-slate-300">طبقة المراقبة</label><Select value={proctoring} onValueChange={value => setProctoring(value as typeof proctoring)}><SelectTrigger className="border-white/10 bg-white/[.03] text-slate-300"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="none">بدون مراقبة</SelectItem><SelectItem value="optional">اختيارية مع موافقة</SelectItem><SelectItem value="required">مطلوبة بموافقة صريحة</SelectItem></SelectContent></Select><p className="text-xs leading-6 text-slate-500">المراقبة لا يتم تفعيلها إلا بعد نافذة موافقة واضحة من المرشح.</p></div></div>}{step === 2 && <div className="grid gap-6">{sections.map((section, sectionIndex) => <section key={sectionIndex} className="rounded-2xl border border-white/10 bg-white/[.02] p-5"><div className="grid gap-3 md:grid-cols-[1fr_1fr]"><Input value={section.title} onChange={event => updateSection(sectionIndex, { title: event.target.value })} className="border-white/10 bg-[#091425] text-white"/><Input value={section.instructions} onChange={event => updateSection(sectionIndex, { instructions: event.target.value })} placeholder="تعليمات القسم" className="border-white/10 bg-[#091425] text-white"/></div><div className="mt-5 grid gap-4">{section.questions.map((question, questionIndex) => <div key={questionIndex} className="rounded-xl border border-white/8 bg-[#081526] p-4"><div className="flex items-center justify-between"><Badge variant="outline" className="border-violet-300/20 bg-violet-300/10 text-violet-200">{labels[question.type]}</Badge><div className="flex items-center gap-2"><Input type="number" min="1" value={question.points} onChange={event => updateQuestion(sectionIndex, questionIndex, { points: Number(event.target.value) })} className="h-8 w-20 border-white/10 bg-white/[.03] text-center text-xs text-white"/><span className="text-xs text-slate-500">نقطة</span></div></div><Textarea value={question.prompt} onChange={event => updateQuestion(sectionIndex, questionIndex, { prompt: event.target.value })} rows={2} className="mt-3 border-white/10 bg-white/[.03] text-white"/><Input value={question.guidance ?? ""} onChange={event => updateQuestion(sectionIndex, questionIndex, { guidance: event.target.value })} placeholder="توجيه أو معيار تقييم اختياري" className="mt-3 border-white/10 bg-white/[.03] text-xs text-white"/>{question.type === "multiple_choice" && <div className="mt-3 grid gap-2">{question.options?.map((option, optionIndex) => <div key={option.id} className="flex items-center gap-2"><Checkbox checked={question.correctAnswers?.includes(option.id)} onCheckedChange={checked => updateQuestion(sectionIndex, questionIndex, { correctAnswers: checked ? [...(question.correctAnswers ?? []), option.id] : (question.correctAnswers ?? []).filter(id => id !== option.id) })}/><Input value={option.label} onChange={event => updateQuestion(sectionIndex, questionIndex, { options: question.options?.map((item, current) => current === optionIndex ? { ...item, label: event.target.value } : item) })} className="h-8 border-white/10 bg-white/[.03] text-xs text-white"/></div>)}</div>}{question.type === "code" && <Textarea value={question.starterCode ?? ""} onChange={event => updateQuestion(sectionIndex, questionIndex, { starterCode: event.target.value })} dir="ltr" rows={5} className="mono mt-3 border-white/10 bg-slate-950 text-left text-xs text-cyan-100"/>}</div>)}</div><div className="mt-4 flex flex-wrap gap-2">{(Object.keys(labels) as QuestionType[]).map(type => <Button key={type} type="button" variant="outline" size="sm" onClick={() => addQuestion(sectionIndex, type)} className="border-white/10 bg-white/[.02] text-xs text-slate-300 hover:bg-white/10 hover:text-white"><Plus className="ml-1 h-3 w-3"/>{labels[type]}</Button>)}</div></section>)}<Button type="button" variant="outline" onClick={() => setSections(previous => [...previous, { title: `قسم ${previous.length + 1}`, instructions: "", questions: [defaultQuestion("essay")] }])} className="border-dashed border-cyan-300/20 bg-cyan-300/5 text-cyan-200 hover:bg-cyan-300/10"><Plus className="ml-2 h-4 w-4"/>إضافة قسم جديد</Button></div>}{step === 3 && <div className="grid gap-5"><div className="rounded-2xl border border-cyan-300/15 bg-cyan-300/5 p-5"><p className="eyebrow">Ready to publish</p><h2 className="mt-2 text-xl font-semibold text-white">{title || "اختبار بدون اسم"}</h2><p className="mt-1 text-sm text-cyan-100">{jobTitle || title || "مسمى وظيفي غير محدد"}</p><p className="mt-2 text-sm leading-7 text-slate-400">{summary || "أضف وصف قبل النشر."}</p><div className="mt-4 flex flex-wrap gap-2 text-xs text-slate-400"><span className="rounded-lg bg-white/[.04] px-2 py-1">{field}</span><span className="rounded-lg bg-white/[.04] px-2 py-1">{duration} دقيقة</span><span className="rounded-lg bg-white/[.04] px-2 py-1">{sections.reduce((sum, section) => sum + section.questions.length, 0)} أسئلة</span></div></div><div className="rounded-xl border border-amber-300/15 bg-amber-400/[.05] p-4 text-sm leading-7 text-amber-100/80"><ShieldCheck className="ml-2 inline h-4 w-4 text-amber-200"/>تأكد إن قواعد المراقبة واضحة ومتوافقة مع سياسة الاحتفاظ بالتسجيلات قبل النشر.</div></div>}<div className="mt-8 flex items-center justify-between border-t soft-divider pt-5"><Button variant="outline" onClick={() => step > 1 && setStep(step - 1)} disabled={step === 1} className="border-white/10 bg-white/[.02] text-slate-300 hover:bg-white/10 hover:text-white">السابق</Button>{step < 3 ? <Button onClick={() => { if (step === 1 && (title.length < 3 || summary.length < 20)) return toast.error("اكتب اسم ووصف واضحين للاختبار الأول."); setStep(step + 1); }} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">التالي<ChevronLeft className="mr-2 h-4 w-4"/></Button> : <Button onClick={submit} disabled={create.isPending} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">{create.isPending ? "جاري النشر..." : "نشر الاختبار"}<Check className="mr-2 h-4 w-4"/></Button>}</div></div></div></PortalShell>;
}

export function CompanyTests() { const tests = trpc.company.tests.mine.useQuery(); const [, setLocation] = useLocation(); return <PortalShell role="company"><div className="page-wrap"><PageHeader eyebrow="Company assessments" title="اختبارات شركتك." text="راجع الحالة والمدة وقواعد المراقبة لكل اختبار." action={<Button onClick={() => setLocation("/company/create-test")} className="bg-cyan-300 text-slate-950"><Plus className="ml-1 h-4 w-4"/>اختبار جديد</Button>}/>{tests.data?.length ? <div className="grid gap-4 lg:grid-cols-2">{tests.data.map(test => <article key={test.id} className="glass-panel p-5"><div className="flex items-start justify-between"><div><h2 className="text-lg font-semibold text-white">{test.title}</h2><p className="mt-2 text-sm leading-6 text-slate-400">{test.summary}</p></div><Badge variant="outline" className={test.status === "published" ? "border-emerald-300/20 text-emerald-300" : "border-slate-300/20 text-slate-400"}>{test.status === "published" ? "منشور" : "مسودة"}</Badge></div><div className="mt-5 flex flex-wrap gap-2 text-xs text-slate-400"><span className="rounded-lg bg-white/[.04] px-2 py-1">{test.field}</span><span className="rounded-lg bg-white/[.04] px-2 py-1">{timeLabel(test.durationMinutes)}</span><span className="rounded-lg bg-white/[.04] px-2 py-1">{test.proctoringMode === "required" ? "مراقبة مطلوبة" : test.proctoringMode === "optional" ? "مراقبة اختيارية" : "بلا مراقبة"}</span></div></article>)}</div> : <Blank title="أنشئ أول اختبار" text="استخدم المعالج عشان تضيف أقسام وأسئلة ومراقبة اختيارية." action={<Button onClick={() => setLocation("/company/create-test")} className="bg-cyan-300 text-slate-950">إنشاء اختبار</Button>}/>}</div></PortalShell>; }

export function CompanyAttempts() { const attempts = trpc.company.attempts.list.useQuery(); const [, setLocation] = useLocation(); return <PortalShell role="company"><div className="page-wrap"><PageHeader eyebrow="Submission queue" title="مراجعة المحاولات." text="الترتيب بالأولوية إشارة مساعدة مبنية على الدرجة ومؤشرات الجلسة، مش قرار توظيف آلي."/>{attempts.data?.length ? <div className="glass-panel overflow-hidden"><div className="overflow-auto"><table className="w-full min-w-[790px] text-right text-sm"><thead className="border-b soft-divider bg-white/[.02] text-xs text-slate-500"><tr><th className="px-5 py-4">المرشح</th><th className="px-5 py-4">الاختبار</th><th className="px-5 py-4">النتيجة</th><th className="px-5 py-4">نزاهة</th><th className="px-5 py-4">الأولوية</th><th className="px-5 py-4">الحالة</th><th className="px-5 py-4"></th></tr></thead><tbody className="divide-y soft-divider">{attempts.data.map(row => <tr key={row.attempt.id} className="hover:bg-white/[.02]"><td className="px-5 py-4"><p className="font-medium text-white">{row.candidate.name ?? "مرشح"}</p><p className="mt-1 text-xs text-slate-500">{row.profile?.headline ?? "ملف مهني"}</p></td><td className="px-5 py-4 text-slate-300">{row.test.title}</td><td className="px-5 py-4 text-slate-300">{percent(row.attempt.reviewerScore ?? row.attempt.autoScore)}</td><td className="px-5 py-4"><span className={row.attempt.integrityFlags ? "text-amber-200" : "text-emerald-300"}>{row.attempt.integrityFlags ? `${row.attempt.integrityFlags} تنبيه` : "سليم"}</span></td><td className="px-5 py-4"><span className="mono text-cyan-200">{row.attempt.priorityScore}</span></td><td className="px-5 py-4"><StatusPill status={row.attempt.applicationStatus}/></td><td className="px-5 py-4"><Button size="sm" variant="outline" onClick={() => setLocation(`/company/review/${row.attempt.id}`)} className="border-white/10 bg-white/[.02] text-slate-300 hover:bg-white/10 hover:text-white">مراجعة</Button></td></tr>)}</tbody></table></div></div> : <Blank title="لا توجد محاولات بعد" text="هنا هتشوف كل التسليمات الخاصة باختبارات شركتك فقط."/>}</div></PortalShell>; }

export function LegacyReviewAttempt() { const [, params] = useRoute("/company/review/:id"); const attemptId = Number(params?.id); const detail = trpc.company.attempts.detail.useQuery({ attemptId }, { enabled: Number.isFinite(attemptId) }); const review = trpc.company.attempts.review.useMutation({ onSuccess: () => { toast.success("تم تحديث حالة المرشح."); detail.refetch(); } }); const [score, setScore] = useState("70"); const [decision, setDecision] = useState<"accepted" | "rejected" | "under review">("under review"); const [notes, setNotes] = useState(""); const data = detail.data; return <PortalShell role="company"><div className="page-wrap"><PageHeader eyebrow="Attempt review" title="مراجعة المحاولة." text="راجع الإجابات وسجل الجلسة ثم حدّث حالة المرشح. المؤشرات مش إثبات مستقل على الغش." action={<Link href="/company/attempts"><Button variant="outline" className="border-white/10 bg-white/[.02] text-slate-300 hover:bg-white/10 hover:text-white">الرجوع للمحاولات</Button></Link>}/>{data ? <div className="grid gap-6 xl:grid-cols-[1fr_360px]"><div className="grid gap-5"><section className="glass-panel p-6"><div className="flex flex-wrap items-center justify-between gap-4"><div className="flex items-center gap-3"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-violet-300/10 text-violet-200"><UserRound className="h-5 w-5"/></span><div><h2 className="font-semibold text-white">{data.candidate?.user.name ?? "مرشح"}</h2><p className="mt-1 text-xs text-slate-500">{data.candidate?.profile?.headline ?? "بدون عنوان مهني"}</p></div></div><div className="flex items-center gap-3"><StatusPill status={data.attempt.applicationStatus}/><span className="mono text-lg text-cyan-200">{data.attempt.priorityScore}</span></div></div><div className="mt-5 grid gap-3 border-t soft-divider pt-5 sm:grid-cols-3"><div><p className="text-xs text-slate-500">الاختبار</p><p className="mt-1 text-sm text-slate-200">{data.test.title}</p></div><div><p className="text-xs text-slate-500">الدرجة التلقائية</p><p className="mt-1 text-sm text-slate-200">{percent(data.attempt.autoScore)}</p></div><div><p className="text-xs text-slate-500">ملف المرشح</p><p className="mt-1 text-sm text-slate-200">{joinSkills(data.candidate?.profile?.skills) || "لا توجد مهارات مضافة"}</p></div></div></section><section className="glass-panel overflow-hidden"><div className="border-b soft-divider px-6 py-4"><h2 className="font-semibold text-white">الإجابات</h2></div><div className="divide-y soft-divider">{data.questions.map(question => { const answer = data.answers.find(item => item.questionId === question.id); return <div key={question.id} className="p-6"><div className="flex items-start justify-between gap-4"><p className="max-w-2xl text-sm leading-7 text-white">{question.prompt}</p><Badge variant="outline" className="shrink-0 border-white/10 text-[10px] text-slate-400">{labels[question.type]}</Badge></div><div className="mt-4 rounded-xl border border-white/8 bg-[#081526] p-4"><pre className="whitespace-pre-wrap break-words text-xs leading-6 text-slate-300">{answer?.codeAnswer || answer?.textAnswer || (answer?.selectedOptionIds?.join(", ")) || "لم يقدّم إجابة"}</pre></div></div>; })}</div></section></div><aside className="grid content-start gap-5"><section className="glass-panel p-5"><div className="flex items-center gap-2"><ShieldAlert className="h-4 w-4 text-amber-200"/><h2 className="font-semibold text-white">مؤشرات الجلسة</h2></div><p className="mt-2 text-xs leading-6 text-slate-500">تُراجع سياقيًا ولا تُستخدم كحكم تلقائي.</p><div className="mt-4 flex items-center justify-between rounded-xl bg-white/[.03] px-3 py-3"><span className="text-sm text-slate-300">تنبيهات النزاهة</span><span className={data.attempt.integrityFlags ? "mono text-amber-200" : "mono text-emerald-300"}>{data.attempt.integrityFlags}</span></div>{data.events.length ? <div className="mt-3 grid gap-2">{data.events.map(event => <div key={event.id} className="rounded-lg border border-white/5 px-3 py-2 text-xs text-slate-400"><span className="text-amber-100">{event.eventType}</span><span className="mr-2 text-slate-600">{new Date(event.occurredAt).toLocaleTimeString("ar-EG")}</span></div>)}</div> : <p className="mt-4 text-sm text-slate-500">لا توجد أحداث مسجلة.</p>}</section><section className="glass-panel p-5"><h2 className="font-semibold text-white">قرار المراجعة</h2><div className="mt-4 grid gap-4"><label className="grid gap-2 text-sm text-slate-400">درجة المراجع<Input type="number" min="0" max="100" value={score} onChange={event => setScore(event.target.value)} className="border-white/10 bg-white/[.03] text-white"/></label><Select value={decision} onValueChange={value => setDecision(value as typeof decision)}><SelectTrigger className="border-white/10 bg-white/[.03] text-slate-300"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="under review">تحت المراجعة</SelectItem><SelectItem value="accepted">قبول</SelectItem><SelectItem value="rejected">رفض</SelectItem></SelectContent></Select><Textarea value={notes} onChange={event => setNotes(event.target.value)} rows={4} placeholder="ملاحظات داخلية للمراجعة..." className="border-white/10 bg-white/[.03] text-white"/><Button onClick={() => review.mutate({ attemptId, score: Number(score), decision, notes: notes || null })} disabled={review.isPending} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">حفظ القرار</Button></div></section></aside></div> : <div className="glass-panel h-96 animate-pulse"/>}</div></PortalShell>; }

export function SupervisorDashboard() { const overview = trpc.supervisor.overview.useQuery(); const [, setLocation] = useLocation(); return <PortalShell role="supervisor"><div className="page-wrap"><PageHeader eyebrow="Supervisor console" title="متابعة المنصة." text="عرض إشرافي للأنشطة والإحصاءات، مع بقاء عزل بيانات كل شركة ومرشح على مستوى الخادم." action={<Button onClick={() => setLocation("/supervisor/attempts")} className="bg-cyan-300 text-slate-950">سجل المحاولات</Button>}/>{overview.data ? <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="مرشحون" value={overview.data.candidateCount} hint="حسابات المرشحين" icon={UserRound}/><Metric label="شركات" value={overview.data.companyCount} hint="مساحات الشركات" icon={BriefcaseBusiness}/><Metric label="اختبارات" value={overview.data.testCount} hint="كل المسودات والمنشور" icon={Layers3}/><Metric label="محاولات" value={overview.data.attemptCount} hint="كل محاولات المنصة" icon={ClipboardIcon}/></div> : <div className="glass-panel h-48 animate-pulse"/>}</div></PortalShell>; }
export function SupervisorAttempts() { const data = trpc.supervisor.attempts.useQuery(); return <PortalShell role="supervisor"><div className="page-wrap"><PageHeader eyebrow="Supervisor audit" title="سجل المحاولات." text="واجهة إشرافية مقيدة بدور المشرف فقط."/>{data.data?.length ? <div className="glass-panel overflow-hidden"><div className="overflow-auto"><table className="w-full min-w-[700px] text-right text-sm"><thead className="border-b soft-divider bg-white/[.02] text-xs text-slate-500"><tr><th className="px-5 py-4">المرشح</th><th className="px-5 py-4">الشركة</th><th className="px-5 py-4">الاختبار</th><th className="px-5 py-4">الحالة</th><th className="px-5 py-4">الأولوية</th></tr></thead><tbody className="divide-y soft-divider">{data.data.map(row => <tr key={row.attempt.id}><td className="px-5 py-4 text-white">{row.candidate.name ?? "مرشح"}</td><td className="px-5 py-4 text-slate-400">{row.company.name}</td><td className="px-5 py-4 text-slate-300">{row.test.title}</td><td className="px-5 py-4"><StatusPill status={row.attempt.applicationStatus}/></td><td className="mono px-5 py-4 text-cyan-200">{row.attempt.priorityScore}</td></tr>)}</tbody></table></div></div> : <Blank title="لا توجد محاولات" text="سيظهر نشاط المنصة هنا بمجرد استلام محاولات."/>}</div></PortalShell>; }

function ClipboardIcon(props: React.ComponentProps<typeof Layers3>) { return <FileCode2 {...props}/>; }

export function LegacyTestRunner() {
  const [, params] = useRoute("/attempt/:id"); const attemptId = Number(params?.id); const payload = trpc.candidate.attempts.get.useQuery({ attemptId }, { enabled: Number.isFinite(attemptId) }); const saveAnswer = trpc.candidate.attempts.saveAnswer.useMutation(); const submit = trpc.candidate.attempts.submit.useMutation({ onSuccess: () => { toast.success("تم تسليم المحاولة."); setLocation("/candidate/status"); }, onError: error => toast.error(error.message) }); const proctor = trpc.proctoring.start.useMutation(); const eventLog = trpc.proctoring.logEvent.useMutation(); const finishProctor = trpc.proctoring.finish.useMutation(); const upload = trpc.files.upload.useMutation(); const [, setLocation] = useLocation();
  const [active, setActive] = useState(0); const [answers, setAnswers] = useState<Record<number, { text?: string; code?: string; selected?: string[]; language?: string; assetId?: number }>>({}); const [seconds, setSeconds] = useState(0); const [consentOpen, setConsentOpen] = useState(false); const [cameraConsent, setCameraConsent] = useState(false); const [screenConsent, setScreenConsent] = useState(false); const [recordConsent, setRecordConsent] = useState(false); const [sessionId, setSessionId] = useState<number | null>(null); const streamRef = useRef<MediaStream[]>([]); const cameraRecorderRef = useRef<MediaRecorder | null>(null); const screenRecorderRef = useRef<MediaRecorder | null>(null); const autosaveTimerRef = useRef<number | null>(null); const pendingAutosaveRef = useRef<{ attemptId: number; questionId: number; textAnswer: string | null; codeAnswer: string | null; selectedOptionIds: string[] | null; language: string | null; fileAssetId: number | null } | null>(null);
  const data = payload.data;
  useEffect(() => { if (!data) return; setSeconds(Math.max(0, Math.floor((new Date(data.attempt.expiresAt).getTime() - Date.now()) / 1000))); const initial: Record<number, { text?: string; code?: string; selected?: string[]; language?: string; assetId?: number }> = {}; data.answers.forEach(answer => { initial[answer.questionId] = { text: answer.textAnswer ?? undefined, code: answer.codeAnswer ?? undefined, selected: answer.selectedOptionIds ?? undefined, language: answer.language ?? undefined, assetId: answer.fileAssetId ?? undefined }; }); setAnswers(initial); }, [data]);
  useEffect(() => { const timer = window.setInterval(() => setSeconds(current => Math.max(0, current - 1)), 1000); return () => window.clearInterval(timer); }, []);
  useEffect(() => { const onHidden = () => { if (sessionId && document.hidden) eventLog.mutate({ sessionId, eventType: "focus_lost", detail: "Document visibility changed to hidden." }); if (sessionId && !document.hidden) eventLog.mutate({ sessionId, eventType: "focus_returned", detail: "Document visibility restored." }); }; document.addEventListener("visibilitychange", onHidden); return () => document.removeEventListener("visibilitychange", onHidden); }, [sessionId]);
  useEffect(() => {
    if (!sessionId || !cameraConsent) return;
    const cameraTrack = streamRef.current[0]?.getVideoTracks()[0];
    if (!cameraTrack) return;
    const onCameraStopped = () => eventLog.mutate({ sessionId, eventType: "camera_stopped", detail: "Camera stopped by candidate or browser." });
    cameraTrack.addEventListener("ended", onCameraStopped);
    return () => cameraTrack.removeEventListener("ended", onCameraStopped);
  }, [sessionId, cameraConsent]);
  const questions = data?.questions ?? []; const question = questions[active]; const current = question ? answers[question.id] ?? {} : {};
  const persistAutosave = async (payloadToSave: NonNullable<typeof pendingAutosaveRef.current>) => { publishAutosaveStatus("saving"); try { await saveAnswer.mutateAsync(payloadToSave); publishAutosaveStatus("saved"); } catch { publishAutosaveStatus("error"); } };
  const flushAutosave = async () => { if (autosaveTimerRef.current) { window.clearTimeout(autosaveTimerRef.current); autosaveTimerRef.current = null; } const pending = pendingAutosaveRef.current; pendingAutosaveRef.current = null; if (pending) await persistAutosave(pending); };
  const setAnswer = (patch: Partial<typeof current>) => { if (!question) return; const next = { ...current, ...patch }; setAnswers(previous => ({ ...previous, [question.id]: next })); const payloadToSave = { attemptId, questionId: question.id, textAnswer: next.text ?? null, codeAnswer: next.code ?? null, selectedOptionIds: next.selected ?? null, language: next.language ?? null, fileAssetId: next.assetId ?? null }; pendingAutosaveRef.current = payloadToSave; if (autosaveTimerRef.current) window.clearTimeout(autosaveTimerRef.current); publishAutosaveStatus("queued"); autosaveTimerRef.current = window.setTimeout(() => { const pending = pendingAutosaveRef.current; pendingAutosaveRef.current = null; autosaveTimerRef.current = null; if (pending) void persistAutosave(pending); }, AUTOSAVE_DELAY_MS); };
  const uploadFile = (file: File | undefined) => { if (!file || !question) return; const reader = new FileReader(); reader.onload = () => { const value = String(reader.result); upload.mutate({ attemptId, category: question.type === "code" ? "code_project" : "evidence", fileName: file.name, mimeType: file.type || "application/octet-stream", dataBase64: value.split(",")[1] ?? "" }, { onSuccess: asset => { setAnswer({ assetId: asset.assetId }); toast.success("تم رفع المرفق وحفظه مع الإجابة."); }, onError: error => toast.error(error.message) }); }; reader.readAsDataURL(file); };
  const uploadRecording = (blob: Blob, category: "camera_recording" | "screen_recording") => { const reader = new FileReader(); reader.onload = () => upload.mutate({ attemptId, category, fileName: `${category}-${Date.now()}.webm`, mimeType: blob.type || "video/webm", dataBase64: String(reader.result).split(",")[1] ?? "" }, { onError: error => toast.error(`تعذر حفظ التسجيل: ${error.message}`) }); reader.readAsDataURL(blob); };
  const startCapture = async () => { try { if (!cameraConsent && !screenConsent) return toast.error("اختار مصدر مراقبة واحد على الأقل."); const camera = cameraConsent ? await navigator.mediaDevices.getUserMedia({ video: true, audio: recordConsent }) : null; const screen = screenConsent ? await navigator.mediaDevices.getDisplayMedia({ video: true, audio: recordConsent }) : null; const session = await proctor.mutateAsync({ attemptId, consentCamera: cameraConsent, consentScreen: screenConsent, consentRecording: recordConsent }); setSessionId(session.id); streamRef.current = [camera, screen].filter(Boolean) as MediaStream[]; if (recordConsent && camera) { const chunks: Blob[] = []; const recorder = new MediaRecorder(camera); recorder.ondataavailable = item => item.data.size && chunks.push(item.data); recorder.onstop = () => uploadRecording(new Blob(chunks, { type: "video/webm" }), "camera_recording"); recorder.start(1000); cameraRecorderRef.current = recorder; } if (recordConsent && screen) { const chunks: Blob[] = []; const recorder = new MediaRecorder(screen); recorder.ondataavailable = item => item.data.size && chunks.push(item.data); recorder.onstop = () => uploadRecording(new Blob(chunks, { type: "video/webm" }), "screen_recording"); recorder.start(1000); screenRecorderRef.current = recorder; screen.getVideoTracks()[0]?.addEventListener("ended", () => eventLog.mutate({ sessionId: session.id, eventType: "screen_stopped", detail: "Screen share ended by candidate." })); } setConsentOpen(false); toast.success("تم تفعيل مراقبة الجلسة بالموافقات اللي اخترتها."); } catch (error) { toast.error(error instanceof Error ? `لم يبدأ التسجيل: ${error.message}` : "تعذر الحصول على صلاحيات المراقبة."); } };
  const stopCapture = () => { void flushAutosave(); cameraRecorderRef.current?.state === "recording" && cameraRecorderRef.current.stop(); screenRecorderRef.current?.state === "recording" && screenRecorderRef.current.stop(); streamRef.current.forEach(stream => stream.getTracks().forEach(track => track.stop())); if (sessionId) finishProctor.mutate({ sessionId }); setSessionId(null); };
  const submitAttempt = async () => { await flushAutosave(); stopCapture(); submit.mutate({ attemptId }); };
  useEffect(() => () => stopCapture(), []);
  const mins = String(Math.floor(seconds / 60)).padStart(2, "0"); const secs = String(seconds % 60).padStart(2, "0");
  if (!data || !question) return <div className="grid min-h-screen place-items-center bg-[#07101f] text-slate-400">جاري تجهيز بيئة الاختبار...</div>;
  return <div className="min-h-screen bg-[#07101f] text-white" dir="rtl"><header className="sticky top-0 z-40 border-b border-white/8 bg-[#07101f]/95 px-4 py-3 backdrop-blur md:px-7"><div className="mx-auto flex max-w-[1560px] items-center justify-between gap-4"><div className="min-w-0"><p className="eyebrow">Assessment runner</p><h1 className="truncate text-sm font-semibold">{data.test?.title}</h1></div><div className="flex items-center gap-3"><span className={`mono rounded-xl border px-3 py-2 text-sm ${seconds < 300 ? "border-rose-300/30 bg-rose-400/10 text-rose-200" : "border-cyan-300/20 bg-cyan-300/10 text-cyan-100"}`}><TimerReset className="ml-2 inline h-4 w-4"/>{mins}:{secs}</span>{data.test?.proctoringMode !== "none" && <Button size="sm" variant="outline" onClick={() => sessionId ? stopCapture() : setConsentOpen(true)} className="border-white/10 bg-white/[.03] text-slate-300 hover:bg-white/10 hover:text-white">{sessionId ? <><Video className="ml-1 h-3.5 w-3.5 text-emerald-300"/>إنهاء المراقبة</> : <><ShieldCheck className="ml-1 h-3.5 w-3.5"/>المراقبة</>}</Button>}<Button size="sm" onClick={submitAttempt} disabled={submit.isPending} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">تسليم</Button></div></div></header><div className="mx-auto grid max-w-[1560px] gap-5 p-4 lg:grid-cols-[250px_1fr] lg:p-7"><aside className="glass-panel order-2 p-4 lg:order-1"><div className="flex items-center justify-between"><p className="text-sm font-semibold">الأسئلة</p><span className="mono text-xs text-slate-500">{active + 1}/{questions.length}</span></div><Progress value={((active + 1) / questions.length) * 100} className="mt-4 h-1.5 bg-white/5"/><div className="mt-5 grid grid-cols-6 gap-2 lg:grid-cols-4">{questions.map((item, index) => <button key={item.id} onClick={() => setActive(index)} className={`grid aspect-square place-items-center rounded-lg text-xs transition ${active === index ? "bg-cyan-300 text-slate-950" : answers[item.id] ? "bg-violet-300/15 text-violet-100" : "bg-white/[.04] text-slate-400 hover:bg-white/[.08]"}`}>{index + 1}</button>)}</div><div className="mt-6 rounded-xl border border-white/7 bg-white/[.02] p-3 text-[11px] leading-6 text-slate-500"><LockKeyhole className="ml-1 inline h-3 w-3 text-cyan-200"/>الإجابات تتعمل لها حفظ تلقائي أثناء الكتابة.</div></aside><main className="glass-panel order-1 p-5 md:p-7 lg:order-2"><div className="flex flex-wrap items-start justify-between gap-4"><div><Badge variant="outline" className="border-violet-300/20 bg-violet-300/10 text-violet-200">{labels[question.type]}</Badge><h2 className="mt-4 max-w-4xl text-xl font-semibold leading-8 text-white">{question.prompt}</h2>{question.guidance && <p className="mt-2 max-w-3xl text-sm leading-7 text-slate-400">{question.guidance}</p>}</div><span className="mono rounded-lg bg-white/[.04] px-2 py-1 text-xs text-slate-400">{question.points} pts</span></div><div className="mt-8">{question.type === "multiple_choice" && <div className="grid gap-3">{question.options?.map(option => { const checked = current.selected?.includes(option.id) ?? false; return <button key={option.id} onClick={() => setAnswer({ selected: checked ? (current.selected ?? []).filter(id => id !== option.id) : [...(current.selected ?? []), option.id] })} className={`flex items-center gap-3 rounded-xl border p-4 text-right text-sm transition ${checked ? "border-cyan-300/35 bg-cyan-300/10 text-white" : "border-white/10 bg-white/[.02] text-slate-300 hover:bg-white/[.05]"}`}><span className={`grid h-5 w-5 place-items-center rounded-full border ${checked ? "border-cyan-200 bg-cyan-300 text-slate-950" : "border-slate-600"}`}>{checked && <Check className="h-3 w-3"/>}</span>{option.label}</button>; })}</div>}{question.type === "essay" || question.type === "vulnerability" ? <Textarea value={current.text ?? ""} onChange={event => setAnswer({ text: event.target.value })} rows={14} placeholder={question.type === "vulnerability" ? "اكتب وصف الثغرة والتأثير وخطوات التحقق الآمنة..." : "اكتب إجابتك هنا..."} className="border-white/10 bg-[#081526] text-base leading-8 text-white placeholder:text-slate-600"/> : null}{question.type === "code" ? <div><div className="mb-3 flex items-center justify-between"><Select value={current.language ?? question.supportedLanguages?.[0] ?? "JavaScript"} onValueChange={language => setAnswer({ language })}><SelectTrigger className="w-44 border-white/10 bg-white/[.03] text-xs text-slate-300"><SelectValue/></SelectTrigger><SelectContent>{(question.supportedLanguages ?? ["JavaScript", "Python"]).map(language => <SelectItem key={language} value={language}>{language}</SelectItem>)}</SelectContent></Select><span className="text-xs text-slate-500">حفظ تلقائي</span></div><Textarea dir="ltr" value={current.code ?? question.starterCode ?? ""} onChange={event => setAnswer({ code: event.target.value })} rows={18} className="mono border-white/10 bg-slate-950 text-left text-sm leading-7 text-cyan-50 placeholder:text-slate-600"/></div> : null}{question.type === "file_upload" ? <div className="rounded-2xl border border-dashed border-cyan-300/25 bg-cyan-300/[.04] p-8 text-center"><FileUp className="mx-auto h-8 w-8 text-cyan-200"/><h3 className="mt-3 font-medium">ارفع دليلك أو تقريرك</h3><p className="mt-2 text-xs leading-6 text-slate-500">الحد الأقصى 10MB. الوصول للملف بيكون مؤقت ومقيّد للصلاحيات.</p><Input type="file" onChange={event => uploadFile(event.target.files?.[0])} className="mx-auto mt-5 max-w-sm border-white/10 bg-white/[.03] text-xs text-slate-300"/>{current.assetId && <p className="mt-4 text-xs text-emerald-300"><Check className="ml-1 inline h-3.5 w-3.5"/>تم ربط المرفق بالإجابة.</p>}</div> : null}</div><div className="mt-8 flex items-center justify-between border-t soft-divider pt-5"><Button variant="outline" onClick={() => setActive(value => Math.max(0, value - 1))} disabled={active === 0} className="border-white/10 bg-white/[.02] text-slate-300 hover:bg-white/10 hover:text-white"><ChevronRight className="ml-1 h-4 w-4"/>السابق</Button><Button variant="outline" onClick={() => setActive(value => Math.min(questions.length - 1, value + 1))} disabled={active === questions.length - 1} className="border-white/10 bg-white/[.02] text-slate-300 hover:bg-white/10 hover:text-white">التالي<ChevronLeft className="mr-1 h-4 w-4"/></Button></div></main></div><Dialog open={consentOpen} onOpenChange={setConsentOpen}><DialogContent className="border-white/10 bg-[#0b1729] text-white" dir="rtl"><DialogHeader><DialogTitle>موافقة المراقبة</DialogTitle><DialogDescription className="leading-7 text-slate-400">اختار بوضوح مصادر المراقبة اللي موافق عليها. لا هيتفتح كاميرا أو مشاركة شاشة أو تسجيل قبل ما تضغط بدء بالموافقات دي.</DialogDescription></DialogHeader><div className="grid gap-4 py-3"><label className="flex items-start gap-3 rounded-xl border border-white/8 p-4"><Checkbox checked={cameraConsent} onCheckedChange={value => setCameraConsent(Boolean(value))}/><span><span className="flex items-center gap-2 text-sm font-medium"><Camera className="h-4 w-4 text-cyan-200"/>الكاميرا</span><span className="mt-1 block text-xs leading-6 text-slate-500">تشغيل فيديو الكاميرا أثناء الاختبار.</span></span></label><label className="flex items-start gap-3 rounded-xl border border-white/8 p-4"><Checkbox checked={screenConsent} onCheckedChange={value => setScreenConsent(Boolean(value))}/><span><span className="flex items-center gap-2 text-sm font-medium"><MonitorUp className="h-4 w-4 text-cyan-200"/>مشاركة الشاشة</span><span className="mt-1 block text-xs leading-6 text-slate-500">اختار نافذة أو شاشة بنفسك من واجهة المتصفح.</span></span></label><label className="flex items-start gap-3 rounded-xl border border-white/8 p-4"><Checkbox checked={recordConsent} onCheckedChange={value => setRecordConsent(Boolean(value))}/><span><span className="flex items-center gap-2 text-sm font-medium"><Video className="h-4 w-4 text-cyan-200"/>تسجيل المصادر المختارة</span><span className="mt-1 block text-xs leading-6 text-slate-500">يتخزن التسجيل بصلاحية وصول مقيدة للمراجعة.</span></span></label></div><DialogFooter><Button variant="outline" onClick={() => setConsentOpen(false)} className="border-white/10 bg-white/[.02] text-slate-300 hover:bg-white/10 hover:text-white">إلغاء</Button><Button onClick={startCapture} disabled={proctor.isPending} className="bg-cyan-300 text-slate-950 hover:bg-cyan-200">بدء بالموافقة المحددة</Button></DialogFooter></DialogContent></Dialog></div>;
}
